const { createHash, randomBytes } = require('node:crypto');

const GUID = '258EAFA5-E914-47DA-95CA-C5AB0DC85B11';

function websocketAccept(secWebSocketKey) {
  return createHash('sha1').update(secWebSocketKey + GUID).digest('base64');
}

function encodeClientTextFrame(text, maskKey = Buffer.from([0x12, 0x34, 0x56, 0x78])) {
  const payload = Buffer.from(text, 'utf8');
  if (payload.length > 125) throw new Error('demo only handles short payloads');
  const frame = Buffer.alloc(2 + 4 + payload.length);
  frame[0] = 0x81; // FIN=1, opcode=0x1(text)
  frame[1] = 0x80 | payload.length; // MASK=1, len<=125
  maskKey.copy(frame, 2);
  for (let i = 0; i < payload.length; i++) {
    frame[6 + i] = payload[i] ^ maskKey[i % 4];
  }
  return frame;
}

function decodeFrame(frame, { fromClient }) {
  const fin = (frame[0] & 0x80) !== 0;
  const opcode = frame[0] & 0x0f;
  const masked = (frame[1] & 0x80) !== 0;
  let len = frame[1] & 0x7f;
  let offset = 2;
  if (len === 126) throw new Error('demo omitted 16-bit extended length');
  if (len === 127) throw new Error('demo omitted 64-bit extended length');
  if (fromClient && !masked) throw new Error('client frame must be masked');
  if (!fromClient && masked) throw new Error('server frame must not be masked');
  const isControl = opcode === 0x8 || opcode === 0x9 || opcode === 0xA;
  if (isControl && (!fin || len > 125)) throw new Error('invalid fragmented/oversized control frame');
  const maskKey = masked ? frame.subarray(offset, offset + 4) : null;
  if (masked) offset += 4;
  const payload = Buffer.alloc(len);
  for (let i = 0; i < len; i++) {
    payload[i] = masked ? frame[offset + i] ^ maskKey[i % 4] : frame[offset + i];
  }
  return { fin, opcode, masked, payload: payload.toString('utf8') };
}

const key = randomBytes(16).toString('base64');
console.log('Sec-WebSocket-Accept:', websocketAccept(key));
const clientFrame = encodeClientTextFrame('hello');
console.log('decoded client frame:', decodeFrame(clientFrame, { fromClient: true }));
const serverPing = Buffer.from([0x89, 0x00]); // FIN=1, opcode=0x9, len=0, unmasked
console.log('decoded server ping:', decodeFrame(serverPing, { fromClient: false }));
try {
  decodeFrame(Buffer.from([0x81, 0x05, ...Buffer.from('hello')]), { fromClient: true });
} catch (err) {
  console.log('protocol error:', err.message);
}
